import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"SQLiteMigrationApplication — takoform_sqlite_migration_application","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/sqlite-migration-application.md","filePath":"proposals/edge/sqlite-migration-application.md"}'),r={name:"proposals/edge/sqlite-migration-application.md"};function n(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="sqlitemigrationapplication-—-takoform-sqlite-migration-application" tabindex="-1">SQLiteMigrationApplication — <code>takoform_sqlite_migration_application</code> <a class="header-anchor" href="#sqlitemigrationapplication-—-takoform-sqlite-migration-application" aria-label="Permalink to &quot;SQLiteMigrationApplication — `takoform_sqlite_migration_application`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An operator attaches one exact ordered SQLite migration set to one exact database and asks the host to apply only its unapplied suffix.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Both <code>database</code> and <code>migrationSet</code> are immutable exact-Form relations; changing either creates another application.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The database carries a durable ordered ledger of migration path and blob digest. Before execution the host proves that ledger is an exact prefix of the referenced <code>MigrationBundle</code>. Removal, reorder, or checksum change fails <code>migration_required</code> and mutates nothing. Each SQL file and its ledger record commit in one SQLite transaction; retry resumes at the first unapplied entry. Applications serialize per database and Ready means ledger equals the exact set (<a href="./../../spec/decisions/0033-edge-app-assets-and-sqlite-migrations-are-content-addressed.html">decision 0033</a>).</p><p>Deleting the attachment stops managing the relationship only. It never runs down SQL, erases ledger entries, changes schema, or deletes the database.</p><p>This administrative path is deliberately separate from <code>edge.sql</code>. Runtime <code>execute</code>, <code>query</code>, and <code>transaction</code> reject durable schema changes, multi-statement input, and transaction-control SQL; only this attachment may advance schema through the exact committed migration history (<a href="./../../spec/decisions/0034-edge-sql-uses-safe-wire-values-and-rollback-only-queries.html">decision 0034</a>).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>The database, desired history, and act of applying that history have distinct lifecycles. The attachment makes their relation explicit and deletion safe.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Rollback, destructive reset, baseline adoption, or repair of a checksum mismatch requires explicit authority and semantics; none is inferred here.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Wrong-kind or unavailable manifests, relation drift, concurrent applications, failed SQL, and rewritten history all fail closed. Database and migration-set deletion are blocked while the attachment lives. Removal does not make the database&#39;s retained data recoverable or disposable; that remains database policy.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>Database-local migration journals that pair an ordered filename with its exact checksum and apply only append-only suffixes.</p>',21)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
